コードのリファクタリングと最適化を行ってください。以下のGo言語による並行処理スニペットには、goroutineリーク、デッドロックの可能性、および不適切なエラーハンドリングが存在します。問題点を列挙し、`context.Context`によるキャンセルと`sync.WaitGroup`を用いた安全な実装に書き直してください:
```go
func FetchAll(urls []string) []string {
    ch := make(chan string)
    for _, u := range urls {
        go func(url string) {
            resp, _ := http.Get(url)
            body, _ := io.ReadAll(resp.Body)
            ch <- string(body)
        }(u)
    }
    var results []string
    for i := 0; i < len(urls); i++ {
        results = append(results, <-ch)
    }
    return results
}
